func encResource(out []byte, v *Resource, depth int) []byte {
	if !(v.Verification).Known() {
		panic(&Refusal{Word: "bad_enum", Offset: 0})
	}
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "handle")
	out = append(out, ':', ' ')
	out = esc(out, v.Handle)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "digest")
	out = append(out, ':', ' ')
	out = esc(out, v.Digest)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "size")
	out = append(out, ':', ' ')
	out = num(out, v.Size)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "verification")
	out = append(out, ':', ' ')
	out = esc(out, v.Verification.String())
	out = append(out, '\n')
	out = pad(out, depth)
	return append(out, '}')
}

